void Servomotor::captureHallSensorData(uint8_t captureType, uint32_t nPointsToRead, uint8_t channelsToCaptureBitmask, uint16_t timeStepsPerSample, uint16_t nSamplesToSum, uint16_t divisionFactor, uint8_t* buffer, uint16_t bufferSize, uint16_t* actualSize) {
    Serial.println("[Motor] captureHallSensorData called.");
    if (buffer == nullptr || bufferSize == 0) {
        _errno = COMMUNICATION_ERROR_BUFFER_TOO_SMALL;
        if (actualSize) *actualSize = 0;
        return;
    }
    const uint8_t commandID = CAPTURE_HALL_SENSOR_DATA;
    captureHallSensorDataPayload payload;
    payload.captureType = captureType;
    payload.nPointsToRead = htole32(nPointsToRead);
    payload.channelsToCaptureBitmask = channelsToCaptureBitmask;
    payload.timeStepsPerSample = htole16(timeStepsPerSample);
    payload.nSamplesToSum = htole16(nSamplesToSum);
    payload.divisionFactor = htole16(divisionFactor);
    sendCommand(commandID, (uint8_t*)&payload, sizeof(payload));
    uint16_t receivedSize = 0;
    _errno = _comm.getResponse((uint8_t*)buffer, bufferSize, receivedSize);
    if (_errno == 0) {
        if (actualSize) *actualSize = receivedSize;
        return;
    }
    if (_errno == COMMUNICATION_ERROR_BUFFER_TOO_SMALL) {
        // getResponse reports the full required payload size in receivedSize.
        if (actualSize) *actualSize = receivedSize;
        return;
    }
    if (actualSize) *actualSize = 0;
}

