getProductSpecsResponse Servomotor::getProductSpecs() {
    Serial.println("[Motor] getProductSpecs called.");
    // Get two product constants needed for motion math: the update frequency in Hz (the rate of the control loop that runs the hall sensor position, movement, PID, and safety calculations) and the number of position counts per one shaft rotation. One time step, as used by 'Move with acceleration', 'Move with velocity', and the other movement commands, is exactly 1/updateFrequency seconds (31250 Hz, i.e. 32 microseconds, on current firmware). countsPerRotation is product-specific (3276800 for M3/M17/M23, 639744 for M1, 4569600 for M2), so always query it rather than hardcoding a value. Sending any payload bytes raises fatal error 51, ERROR_COMMAND_SIZE_WRONG.
    const uint8_t commandID = GET_PRODUCT_SPECS;
    sendCommand(commandID, nullptr, 0);
    uint8_t buffer[sizeof(getProductSpecsResponse)];
    uint16_t receivedSize;
    _errno = _comm.getResponse(buffer, sizeof(buffer), receivedSize);
    if (_errno == 0) {
        if (receivedSize == sizeof(getProductSpecsResponse)) {
            getProductSpecsResponse* response = (getProductSpecsResponse*)buffer;
            return *response;
        } else {
            _errno = COMMUNICATION_ERROR_DATA_WRONG_SIZE;
        }
    }
    getProductSpecsResponse defaultResponse = {0};
    return defaultResponse;
}

