void Servomotor::getProductDescription(char* buffer, uint16_t bufferSize, uint16_t* actualSize) {
    Serial.println("[Motor] getProductDescription called.");
    if (buffer == nullptr || bufferSize == 0) {
        _errno = COMMUNICATION_ERROR_BUFFER_TOO_SMALL;
        if (actualSize) *actualSize = 0;
        return;
    }
    const uint8_t commandID = GET_PRODUCT_DESCRIPTION;
    sendCommand(commandID, nullptr, 0);
    uint16_t receivedSize = 0;
    _errno = _comm.getResponse((uint8_t*)buffer, bufferSize, receivedSize);
    if (_errno == 0) {
        // Guarantee a null terminator inside the caller's buffer.
        // getResponse only returns success when the data fit, so here
        // receivedSize <= bufferSize. A string_null_term already carries
        // its terminator on the wire; this makes termination certain even
        // if a future string type does not.
        if (receivedSize < bufferSize) {
            buffer[receivedSize] = '\0';
        } else {
            buffer[bufferSize - 1] = '\0';
        }
        if (actualSize) *actualSize = (uint16_t)strlen(buffer);
        return;
    }
    if (_errno == COMMUNICATION_ERROR_BUFFER_TOO_SMALL) {
        // getResponse reports the full required payload size in receivedSize.
        if (actualSize) *actualSize = receivedSize;
        buffer[0] = '\0';
        return;
    }
    if (actualSize) *actualSize = 0;
    buffer[0] = '\0';
}

