    const uint8_t commandID = SYSTEM_RESET;
    _comm.sendCommandByUniqueId(uniqueId, commandID, nullptr, 0);
    uint16_t receivedSize;
    _errno = _comm.getResponse(nullptr, 0, receivedSize);
