int64_t Servomotor::getPositionRaw() {
    Serial.println("[Motor] getPositionRaw called.");
    // Get the current commanded (desired) position, i.e. the motion profile's internal target position that advances every control tick. This may differ slightly from the actual position measured by the hall sensors, which is available via 'Get hall sensor position'. Executes immediately (it is not queued), can be sent at any time including during motion, and takes an atomic snapshot with interrupts disabled. Commanded and measured position live in the same internal count space, so the same position unit conversion applies to both. The payload must be empty; any payload bytes raise fatal error 51, ERROR_COMMAND_SIZE_WRONG. Broadcast produces no response and has no side effects. (Raw version)
    const uint8_t commandID = GET_POSITION;
    sendCommand(commandID, nullptr, 0);
    uint8_t buffer[sizeof(getPositionResponse)];
    uint16_t receivedSize;
    _errno = _comm.getResponse(buffer, sizeof(buffer), receivedSize);
    if (_errno == 0) {
        if (receivedSize == sizeof(getPositionResponse)) {
            getPositionResponse* response = (getPositionResponse*)buffer;
            return response->position;
        } else {
            _errno = COMMUNICATION_ERROR_DATA_WRONG_SIZE;
        }
    }
    getPositionResponse defaultResponse = {0};
    return defaultResponse.position;
}

int64_t Servomotor::getPositionRaw(uint64_t uniqueId) {
    Serial.println("[Motor] getPositionRaw called (by unique ID).");
    // Get the current commanded (desired) position, i.e. the motion profile's internal target position that advances every control tick. This may differ slightly from the actual position measured by the hall sensors, which is available via 'Get hall sensor position'. Executes immediately (it is not queued), can be sent at any time including during motion, and takes an atomic snapshot with interrupts disabled. Commanded and measured position live in the same internal count space, so the same position unit conversion applies to both. The payload must be empty; any payload bytes raise fatal error 51, ERROR_COMMAND_SIZE_WRONG. Broadcast produces no response and has no side effects. (Raw version)
    const uint8_t commandID = GET_POSITION;
    _comm.sendCommandByUniqueId(uniqueId, commandID, nullptr, 0);
    uint8_t buffer[sizeof(getPositionResponse)];
    uint16_t receivedSize;
    _errno = _comm.getResponse(buffer, sizeof(buffer), receivedSize);
    if (_errno == 0) {
        if (receivedSize == sizeof(getPositionResponse)) {
            getPositionResponse* response = (getPositionResponse*)buffer;
            return response->position;
        } else {
            _errno = COMMUNICATION_ERROR_DATA_WRONG_SIZE;
        }
    }
    getPositionResponse defaultResponse = {0};
    return defaultResponse.position;
}

float Servomotor::getPosition() {
    Serial.println("[Motor] getPosition called.");
    auto rawResult = getPositionRaw();
    float converted = ::convertPosition((float)rawResult, m_positionUnit, ConversionDirection::FROM_INTERNAL);
    return converted;
}

float Servomotor::getPosition(uint64_t uniqueId) {
    Serial.println("[Motor] getPosition called (by unique ID).");
    auto rawResult = getPositionRaw(uniqueId);
    float converted = ::convertPosition((float)rawResult, m_positionUnit, ConversionDirection::FROM_INTERNAL);
    return converted;
}

void Servomotor::readMultipurposeBuffer(uint8_t* buffer, uint16_t bufferSize, uint16_t* actualSize) {
    Serial.println("[Motor] readMultipurposeBuffer called.");
    if (buffer == nullptr || bufferSize == 0) {
        _errno = COMMUNICATION_ERROR_BUFFER_TOO_SMALL;
        if (actualSize) *actualSize = 0;
        return;
    }
    const uint8_t commandID = READ_MULTIPURPOSE_BUFFER;
    sendCommand(commandID, nullptr, 0);
    uint16_t receivedSize = 0;
    _errno = _comm.getResponse((uint8_t*)buffer, bufferSize, receivedSize);
    if (_errno == 0) {
        if (actualSize) *actualSize = receivedSize;
        return;
    }
    if (_errno == COMMUNICATION_ERROR_BUFFER_TOO_SMALL) {
        // getResponse reports the full required payload size in receivedSize.
        if (actualSize) *actualSize = receivedSize;
        return;
    }
    if (actualSize) *actualSize = 0;
}

void Servomotor::readMultipurposeBuffer(uint64_t uniqueId, uint8_t* buffer, uint16_t bufferSize, uint16_t* actualSize) {
    Serial.println("[Motor] readMultipurposeBuffer called (by unique ID).");
    if (buffer == nullptr || bufferSize == 0) {
        _errno = COMMUNICATION_ERROR_BUFFER_TOO_SMALL;
        if (actualSize) *actualSize = 0;
        return;
    }
    const uint8_t commandID = READ_MULTIPURPOSE_BUFFER;
    _comm.sendCommandByUniqueId(uniqueId, commandID, nullptr, 0);
    uint16_t receivedSize = 0;
    _errno = _comm.getResponse((uint8_t*)buffer, bufferSize, receivedSize);
    if (_errno == 0) {
        if (actualSize) *actualSize = receivedSize;
        return;
    }
    if (_errno == COMMUNICATION_ERROR_BUFFER_TOO_SMALL) {
        // getResponse reports the full required payload size in receivedSize.
        if (actualSize) *actualSize = receivedSize;
        return;
    }
    if (actualSize) *actualSize = 0;
}

void Servomotor::testMode(uint8_t testMode) {
    Serial.println("[Motor] testMode called.");
    // Set or trigger a test mode. Executes immediately (not queued); intended only for developers and production testing. As of firmware 0.15.4.0, value 0 safely clears all test modes (motor test mode, overtemperature test mode, and the overvoltage-threshold override). WARNING for firmware before 0.15.4.0: value 0 hangs the device forever before any reply and only a power cycle recovers it -- on older firmware clear test modes only with 'System reset'. Of motor test modes 1-9, only 2, 3 and 4 do anything: 2 suppresses the fatal error on a failed 'Go to closed loop' (the device drops back to open loop with MOSFETs disabled instead), 3 captures one PID debug snapshot (error, P/I/D terms, output) into the multipurpose buffer (read it with 'Read multipurpose buffer'), and 4 formerly read the GC6609 driver registers into that buffer, but is DEFUNCT on current units (the GC6609 is used only on legacy M17 units with software compatibility code 1; on current hardware the buffer stays empty and the mode stays latched until reset). Any nonzero motor test mode makes 'Start calibration' raise fatal error ERROR_TEST_MODE_ACTIVE. LED test modes 10-13 (10=both LEDs off, 11=green on, 12=red on, 13=both on) send the success response and then hang forever; power cycle required. Values 14-73 deliberately trigger fatal errors 0-59 (value minus 14): no success response is sent -- the device replies with an error packet and stays in the fatal-error state until 'System reset'. Value 14 raises fatal error 0, which shows a solid red LED while the status error code reads 0 and is easily mistaken for no error. Value 74 sets the overvoltage-protection threshold to 22 V (production test; should trip on a 24 V supply), 75 sets it to 26 V (should not trip on 24 V), and 76 raises the overtemperature cutoff to about 90 degrees C (default about 80); these take effect immediately and only a reset restores the defaults. Values above 76 raise fatal error 53, ERROR_INVALID_TEST_MODE. Values 0-9 and 74-76 return a success response, as do LED modes 10-13 (which hang immediately after sending it); values 14-73 and values above 76 reply with an error packet instead. Broadcast executes with no reply; broadcasting 10-13 bricks every device on the bus until power cycled (broadcasting 0 does too, but only on firmware before 0.15.4.0).
    const uint8_t commandID = TEST_MODE;
    testModePayload payload;
    payload.testMode = testMode;
    sendCommand(commandID, (uint8_t*)&payload, sizeof(payload));
    uint16_t receivedSize;
    _errno = _comm.getResponse(nullptr, 0, receivedSize);
}

